import{_ as i,O as a,o as r,c as s,a as n,i as d,f as o}from"./chunks/framework.fmIt2z2h.js";const T=JSON.parse('{"title":"A.7　HV07 反馈写回（完整接口卡）","description":"","frontmatter":{"title":"A.7　HV07 反馈写回（完整接口卡）","xkChars":1760,"xkLessons":{"A.7":{"title":"A.7　HV07 反馈写回（完整接口卡）","lead":"HV07让回执、更新、执行、反馈效应和学习分别结案；有效写回不自动等于正确纠错或全面改善。","explanation":["原文定位：第3964—4029行，原站定位/theory/appendix-a/a-07#section-a-7。本题切片及完整用户原稿均在source目录，可逐字回查。","短引文：“一次写回不称学习，写回也不等正确纠错。”HV07区分反馈有没有到达、字段有没有改变、改变是否执行，以及后续是否保留、调用并产生任务层面作用。申诉、审计或反馈只有改变记录、规则、资源、角色、责任、记忆或停止条件且实际执行，才在本接口称制度写回。[T-main；T-H3]","HV07-R0-writeback-classification依D2与H3检查输入、回执、版本、执行、生效、持续及停止回滚状态，区分未提交、已提交、已受理、字段改变、已执行、持续或失效。接收或表态没有更新时，暂停的是“制度写回成立”的断言，不是把已被安全听取的价值取消。[T-main；T-D2]","有理由维持决定的程序也可能有价值，不能为了提高改判率而强迫每个申诉都改结果。应分别核是否有回应、证据是否理解、错误是否纠正、资源权利是否恢复。写回还可能写错、扩大伤害或由有利反馈造成偏差；有效性与内容正当性分别判断。[T-main；T-state]","HV07-R1-causal-feedback要求合格G2显示返回通道相对无返回或阻断改变预选后续状态/转移，并加CAUSAL/E4。登记的是指定字段、通道、窗口内的反馈和写回效应；不能因为存在返回路径就推长期修复、目标正确或授权扩大。[T-main；T-G2]","HV07-R2-feedback-mediated-learning要求有效反馈G2以及G3支持可保留更新在重复轮次对预定任务有当前表示之外的历史条件增量。其结论只到任务、轮次、窗口内的历史增量型学习候选，不能称整体制度已学会、价值方向正确或全面修复完成。[T-main；T-history]","HV07-R3-carried-learning是另一条路线：有效反馈已有G2，再按C3-carried-learning与§4.5核当前更新载体、跨轮保留、实际调用、预定任务比较和因果依据。即时反馈实例不自动覆盖后续结果。它支持限定载体、任务、轮次内的载体传递型学习候选，不取得G3/CM-LEARNING-history资格，但G3未支持也不取消有独立材料的这条路线。[T-main；T-history；T-learning]","训练、归档、发布或一次成功都不足以单独称学习；一般学习、跨任务迁移与净收益也应分别结案。更新被保存却从未调用，会卡在学习依据；更新被调用但使目标错误率更高，则需按预定任务比较记录，不能用“系统确实变了”宣称改善。[T-main]","九轴记录反馈跨层路径及分辨率损失。个案不自动代表总体，未提交可能源于无数字接入、安全威胁或保护性匿名；不能把沉默当同意，也不能按回执数量证明所有位置已覆盖。受理者、决定者、写回执行者、监督者责任分开，状态时限与结果可被独立复核。[T-main]","获准回滚时撤销错误更新并实际恢复相应记录、规则、资源、角色或停止条件，保留版本与完成验证。模块只生成复核/程序修复需求，不自行改记录、关申诉或执行修复；保护需求也不自动增权。[T-main]","Robodebt官网明载报告发布与更正版日期，又列一线反馈和自动化复核建议。版本公告、建议文本、机构执行和居民实际补救是不同材料；本题只读官网，未做PDF差分或落实调查，所以不把更正公告和建议发布写成全制度已学习。[P-ROBO]","39字段逐项研读（以下“原卡”保留该字段全部内容；“解读”明确其作用和不可替代的责任）。","01｜接口 ID（id）。原卡：HV07 解读：这是卡册内的短标识，追踪同一接口，不表示现实对象已被证明。 [T-main]","02｜限定 ID（qualified_id）。原卡：human_variable:HV07 解读：限定命名空间用于避免同名碰撞；引用此ID仍须携带对象和证据状态。 [T-main]","03｜名称（name）。原卡：反馈写回 解读：名称给出阅读入口，不是对具体人、群体或现实结构的自动标签。 [T-main]","04｜主张类型（claim_type）。原卡：H 解读：H表示人类实例/接口命题的角色；不能把它升级为形式证明或无条件世界规律。 [T-main]","05｜合同角色（contract_role）。原卡：human_variable_interface 解读：这是变量接口合同，规定怎样接入分析；字段存在不等于经验实例已经成立。 [T-main]","06｜命题（proposition）。原卡：申诉、审计和反馈只有改变记录、规则、资源、角色、责任、记忆或停止条件，且相应改变已实际执行时，才构成人类制度写回。 解读：这条命题必须连同后面的条件路由和上限理解，不能从一句话抽出无条件因果或规范结论。 [T-main]","07｜适用范围（scope）。原卡：具有反馈、申诉、审计或治理程序的人类结构 解读：范围列出可考察的任务领域，不代表范围内所有对象已获实证支持。 [T-main]","08｜暂停条件（pause_condition）。原卡：只有接收回执、表态或发布而无状态更新，或字段改变尚未实际执行时，暂停制度性写回成立断言；已提交、已受理、字段改变等有限状态仍按R0分类。 解读：只有回执、表态、发布或未执行字段修改时，暂停制度写回成立断言，仍保留R0已提交/受理等有限成果。 [T-main]","09｜推理依赖（inferential_requires）。原卡：1. D2 解读：推理依赖提供命题成立所需的上游内容；上游的候选/支持状态必须原样传递，引用不自动升格。 [T-main]","10｜协议依赖（protocol_requires）。原卡：1. EVIDENCE；2. SOURCE 解读：协议依赖约束取证和表达方式；完成协议不单独证明经验命题为真。 [T-main]","11｜限定／特化（specializes）。原卡：1. H3 解读：H3是制度写回分类规则，按实际完成位置分类；它本身不是经验效果证据，更不要求所有有价值申诉必须改变原决定。 [T-main]","12｜适用对象引用（applies_to）。原卡：无（空集合） 解读：适用对象引用不能代替当前对象合同；空集合是明确登记，不是所有对象都可用。 [T-main]","13｜条件支持路由（conditional_support_routes）。原卡：1. route_id=HV07-R0-writeback-classification；；claim_level=descriptive_classification；；when=输入通道、回执、字段前后版本、执行记录、生效时间、持续时间及停止或回滚状态可分别检查。；；additional_inferential_requires=无（空集合）；；additional_protocol_requires=无（空集合）；；allowed_conclusion=区分未提交、已提交、已受理、字段改变、已执行、持续或失效的写回状态。；；result_ceiling=只有字段改变且实际执行才称制度性写回；一次写回不称学习，写回也不等正确纠错。有理由维持决定的程序价值和其他已发生变化按各自证据保留。；2. route_id=HV07-R1-causal-feedback；；claim_level=mechanism_explanation；；when=符合资格的G2-instance显示制度返回通道相对无返回或阻断条件改变预选后续状态或转移。；；additional_inferential_requires=G2-instance；；additional_protocol_requires=CAUSAL、E4；；allowed_conclusion=登记指定字段、通道和窗口内的有效反馈与制度写回效应。；；result_ceiling=不得从反馈存在推出学习、长期修复、正当性或授权扩大。；3. route_id=HV07-R2-feedback-mediated-learning；；claim_level=intertemporal_explanation；；when=有效反馈已有G2-instance支持，且G3-instance显示可保留更新在重复轮次对预定任务提供历史条件增量。；；additional_inferential_requires=G2-instance、G3-instance；；additional_protocol_requires=CAUSAL、E4；；allowed_conclusion=登记限定任务、轮次和窗口内、当前状态之外的历史增量型反馈介导学习候选。；；result_ceiling=不得称整体制度已经学习、修复完成或价值方向正确。；4. route_id=HV07-R3-carried-learning；；claim_level=intertemporal_explanation；；when=有效反馈已有符合资格的G2-instance支持，且按C3-carried-learning与§4.5核实当前更新载体、跨轮保留和实际调用、预定任务比较及其因果依据；即时反馈实例不自动覆盖后续任务结果。；；additional_inferential_requires=G2-instance；；additional_protocol_requires=CAUSAL、E4；；allowed_conclusion=登记指定更新载体、任务和轮次内的载体传递型反馈介导学习候选。；；result_ceiling=不取得CM-LEARNING-history或G3的历史增量资格，不把训练、归档、写回或一次成功直接称为学习，不宣称整体制度已改善。 解读：R0过程分类；R1 G2返回通道效应；R2 G2＋G3历史增量型学习；R3 G2＋更新载体保留调用和任务比较的载体型学习。不得把一次更新直升任一路学习。 [T-main]","14｜允许推论（allowed_inference）。原卡：1. 有效写回、阻塞写回与表面反馈 解读：这是允许谈论的结论方向；实际达到哪一项、到什么强度，仍由所选路由及材料限定。 [T-main]","15｜禁止跳跃（prohibited_leap）。原卡：1. 有渠道即会学习；2. 一次更新即长期修复；3. 沉默即同意 解读：这些是常见越界，不是换个措辞就能避开；检查实际推断和后续使用，而非只看用词。 [T-main]","16｜九轴尺度画像（scale_profile）。原卡：SP=<A,X,T,O,C,R,I,N,J>；A=聚合层次：单次反馈或申诉、写回个案、反馈总体、受理执行分布及聚合规则；X=空间范围：提交渠道、组织或平台边界、制度辖区与跨域申诉范围；T=时间跨度：提交、受理、字段变化、执行、持续与复核时滞；O=组织层级：反馈角色、受理团队、组织、制度至治理生态；C=因果层次：反馈事件、写回互动机制、中观程序结构、制度规则与系统条件；R=观察分辨率：原始反馈、处理序列、写回个案、结果分布、时效指标与摘要，并登记压缩损失；I=影响范围：直接申诉人与承接者、间接受影响者、二阶制度后果、跨域与代际影响；N=网络拓扑范围：反馈通道、受理节点、复核路径、阻塞点与跨层连接；J=管辖与授权范围：受理、字段修改、执行、停止、回滚与补救分别登记授权；登记跨层路径 解读：九轴逐项登记；尤其影响范围I不产生管辖权限J，观察分辨率R降低时须保留压缩损失。 [T-main]","17｜有效对象（effective_object）。原卡：改变后续制度状态或转移的返回通道 解读：这是该接口对应的对象描述；若选择低门槛描述路由，不能把名称中的功能含义当作因果已证。 [T-main]","18｜跨尺度保持项（scale_invariants）。原卡：1. 反馈来源、通道、写回字段和后续变化 解读：保持项是迁移时须守住的比较责任，不是宣称所有尺度上的变量数值不变。 [T-main]","19｜升格必补项（required_scale_additions）。原卡：1. 反馈代表性；2. 跨层写回路径；3. 聚合损失；4. 外部复核 解读：升格不是把原表复制放大。新增总体、接口和责任位置等材料未齐时，限制依赖它们的结论。 [T-main]","20｜随尺度改变项（changing_semantics）。原卡：1. 写回载体、时滞和责任主体可改变 解读：同一词在对象或尺度改变后可能变义，应重建对应而非假定原含义原样适用。 [T-main]","21｜不适用对象（non_applicable_objects）。原卡：1. 无记录、规则、资源、角色或停止条件的过程 解读：不适用约束防止人类规范、责任和体验接口被无条件投射；不等于否认其他理论可研究这些对象。 [T-main]","22｜禁止升格（forbidden_elevation）。原卡：1. 个案反馈直接代表总体意见 解读：局部向整体的推断必须另证；影响广、名称大或形式相似都不能补代表性和授权。 [T-main]","23｜状态集合（state）。原卡：1. 到达；2. 受理；3. 写回；4. 阻塞；5. 失真 解读：状态是待证描述分类，不是给人评分的成熟阶梯；状态改变须有窗口、依据与版本。 [T-main]","24｜可观测项（observables）。原卡：1. 反馈或申诉的提交与受理凭证；2. 记录、规则、资源、角色、责任或停止条件的版本差异；3. 变更的执行记录、生效时间与持续时间；4. 复核、撤销、补救及后续状态变化 解读：可观测线索回答到哪里找材料；单一线索的存在还不是完整机制或因果效应的证明。 [T-main]","25｜证据要求（evidence）。原卡：1. 反馈原文；2. 受理轨迹；3. 字段版本；4. 后续规则或资源变化 解读：证据清单按路由和任务相关性取得；未知、未收集、不适用、受保护不可得分开，不为填满表强制披露。 [T-main]","26｜输入依赖与接口内容（input_dependencies）。原卡：1. 反馈来源；2. 安全通道；3. 责任人；4. 复核程序 解读：这里说明上游传入什么及其资格；缺口不能在接口间传递时被悄悄抹掉。 [T-main]","27｜输出效应与变量流（output_effects）。原卡：1. 记录、规则、资源、角色、责任、记忆或停止条件更新 解读：原卡列更新种类；实际是哪一字段改变及执行、何时生效，需要版本和外部状态，不能因列有七种就说全部更新。 [T-main]","28｜时间窗与时滞（time_window_and_lag）。原卡：登记提交、受理、决定、执行和复审时限 解读：发生、观察、执行和效果到达可能不同时；窗口外延不能由短期材料自动认证。 [T-main]","29｜不确定性（uncertainty）。原卡：记录未达反馈、保护性匿名与不可见处理 解读：把不确定性指向具体材料和位置，不能只写一个总置信分而掩盖根本未覆盖的位置。 [T-main]","30｜局部排除区（local_exclusion_zone）。原卡：无法安全提交、受反报复威胁或无数字接入的位置 解读：排除区限制当前推断覆盖，不是把这些人或事实从世界删除；安全不可得也不是同意或无问题。 [T-main]","31｜受影响位置（affected_positions）。原卡：1. 提交者；2. 被评价者；3. 执行者；4. 制度受益者 解读：同时登记直接和间接受影响者；可见成员不代表全部成本承担者。 [T-main]","32｜承接载体（carrier）。原卡：1. 申诉系统；2. 审计程序；3. 会议记录；4. 规则库；5. 责任链 解读：载体是实际承载的结构或过程；载体名称、建设完成和所需功能到达是不同证据。 [T-main]","33｜责任主体（responsible_subject）。原卡：1. 受理者；2. 决策者；3. 写回执行者；4. 监督者 解读：说明谁提出判断、谁操作或使用；责任登记不自动等于法律责任裁判或新授权。 [T-main]","34｜规范地位（normative_status）。原卡：反馈有效性与反馈内容正当性分别判断 解读：通道有效可能传回错误或不正当内容。是否正确纠错、保护当事人以及整体净收益，不能由写回事实直接推出。 [T-main]","35｜判断上限（judgment_ceiling）。原卡：R0判断写回过程的实际完成位置；R1在相应G2支持下判断返回通道效应；R3依更新保留、跨轮调用及任务比较判断载体型反馈介导学习；R2另有G3时才判断历史增量型学习。一次写回、一般学习、迁移与净收益分别结案。 解读：完成位置、通道效应、载体型学习、历史增量型学习分开；一般学习、迁移、净收益也不共用结案。 [T-main]","36｜行动上限（action_ceiling）。原卡：本变量只生成受理、字段变化、执行、持续时间与写回缺口描述，以及复核或程序修复需求，不授权改写记录规则、执行修复或关闭申诉；任何现实调整须另过C12、运行时显式N前提、J授权与O程序 解读：接口本身不产生现实处置权；实际动作另核选择、C12、显式N、有效J、O及保护和期限。 [T-main]","37｜反例（counterexamples）。原卡：1. 申诉获得接收回执但记录、规则、资源和停止条件均未改变；2. 审计报告被发布却没有责任人、时限或后续状态更新 解读：用反例限定无条件外推；反例可能要求缩小范围或重新取证，不自动否定所有有限用法。 [T-main]","38｜申诉（appeal）。原卡：依appeal_and_rollback_rule，反馈提交者可经安全可达、反报复通道要求状态、时限、责任人与写回结果，并触发与原受理、写回或决策链独立的复核 解读：申诉要安全可达、免于报复并能触发独立复核；只留一个名称不代表有权改变错误。 [T-main]","39｜回滚（rollback）。原卡：依appeal_and_rollback_rule，获准回滚时，由指定责任人在规定时限内撤销错误更新，实际恢复先前记录、规则、资源、角色或停止条件状态，保留版本与完成验证 解读：在有效授权内实际撤销错误效力、纠正下游并验证完成；文档改字不等于权利资源恢复到当事人。 [T-main]"],"argumentSteps":["按R0查输入、受理、字段版本、实际执行与持续状态。","保留已听取和有理由维持决定的程序价值，不强求改判。","R1以G2比较返回与阻断的后续状态。","学习另核跨轮更新：R2查G3当前外历史增量，R3查当前载体保留调用与任务比较。","一般学习、迁移、净收益及修复分别评价。","保护未安全进入者，允许独立复核；获准后实际回滚错误更新。"],"distinctions":[{"leftTitle":"已受理","leftText":"反馈得到正式接收。","rightTitle":"制度写回","rightText":"字段改变且实际执行。"},{"leftTitle":"写回发生","leftText":"系统状态改变。","rightTitle":"正确纠错","rightText":"还需事实、规范及恢复到达。"},{"leftTitle":"R2历史学习","leftText":"当前表示之外历史增量。","rightTitle":"R3载体学习","rightText":"当前更新保留调用及预定任务比较。"},{"leftTitle":"一次成功","leftText":"一个任务窗口中的结果。","rightTitle":"迁移和净收益","rightText":"跨任务、成本副作用需另验。"}],"boundaries":["原卡反例：申诉有回执而记录规则资源停止条件均未变。","原卡反例：审计发布却无责任人、时限或后续更新。","教学反例：为提高改判率随意改正确决定，不能称更好纠错。","原文边界：缺G3不否定有独立材料的R3载体传递学习。"],"questions":["没有改变原决定的申诉是否全无价值？","一次写回能否说制度学会了？","R3是否自动获得G3资格？","反馈有效是否一定正确？"],"diagramPath":"/reading-assets/S-A-7/figures/hv07-status.png","caseLinks":[{"title":"Robodebt报告发布、更正说明与改革建议","href":"https://robodebt.royalcommission.gov.au/publications/report"}],"caseNotes":[{"title":"Robodebt报告发布、更正说明与改革建议","text":"官网记载2023年7月7日报告与7月11日更正版，并列一线反馈和自动化复核建议。","sourceLabel":"Royal Commission into the Robodebt Scheme：Report官网","sourceUrl":"https://robodebt.royalcommission.gov.au/publications/report","sourceLocator":"报告版本说明（网页行29—54）及建议13.1—13.2、17.1（行101—107、149—156）","boundary":"只证明官网的版本说明和建议内容；未核PDF逐项差分、改革落实或实际补救，不能据此称全制度已学习。","href":"https://robodebt.royalcommission.gov.au/publications/report"}],"sourceRefs":[{"section":"A.7","start_line":3964,"end_line":4029,"startLine":3964,"endLine":4029}],"outputId":"section-a-7","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","teachingExamples":[{"title":"教学构造：四个状态不共用一个完成标记","text":"人工申诉周一提交、周二受理、周四字段修改、下周一才实际执行资源恢复。周二可记受理，不能称资源已恢复；周四有字段变化也不足证明执行。下周一相应恢复到达后，仍不凭一次案例证明整个制度长期学习或净收益为正。","assumptions":"虚构时间线和资源记录。","boundary":"真实恢复及授权须独立证据；不否认听取和受理本身的有限价值。"},{"title":"教学构造：保留更新仍要被调用并比较","text":"人工程序把一次纠错规则保存到版本v2，后续三轮却仍运行v1。归档事实不证明v2产生学习效果。若后来三轮实际调用v2，仍须预定任务比较与因果材料；是否另有当前表示之外的历史增量，则再按G3检验，不把调用次数当万能证明。","assumptions":"程序版本和轮次人工设定。","boundary":"R3不要求额外G3，但要求自身保留、调用和任务比较；R2另有历史增量责任。"}],"counterexamples":[{"identity":"source_counterexample","text":"原卡反例：申诉有回执而记录规则资源停止条件均未变。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原卡反例：审计发布却无责任人、时限或后续更新。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"constructed_boundary","text":"教学反例：为提高改判率随意改正确决定，不能称更好纠错。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：缺G3不否定有独立材料的R3载体传递学习。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]}],"questionAnswers":[{"question":"没有改变原决定的申诉是否全无价值？","answer":"不；有理由维持、听取和其他实际变化按独立证据保留。","basis":"R0结论上限。"},{"question":"一次写回能否说制度学会了？","answer":"不能；跨轮保留调用、任务比较及相应路线另核。","basis":"R2/R3。"},{"question":"R3是否自动获得G3资格？","answer":"不；载体传递型不等于当前表示外历史增量。","basis":"R3上限。"},{"question":"反馈有效是否一定正确？","answer":"不；内容正当和正确纠错分别判断。","basis":"normative_status。"}],"figures":[{"path":"/reading-assets/S-A-7/figures/hv07-status.png","alt":"提交受理、字段改变、实际执行、持续或失效分别记录；制度写回不自动等于正确纠错。","caption":"据A.7 R0与原文状态字段。"},{"path":"/reading-assets/S-A-7/figures/hv07-routes.png","alt":"R0分类、R1G2反馈、R2G2加G3历史学习、R3G2与当前载体保留调用任务比较；不得混同。","caption":"据A.7四条路由。"},{"path":"/reading-assets/S-A-7/figures/hv07-learning.png","alt":"一次更新、一般学习、跨任务迁移、净收益分别取证；保存不等调用，调用不等有益。","caption":"据A.7 judgment_ceiling。"}],"diagramBrief":"第一图区分完成位置，第二图列四路线，第三图区分学习、迁移、净收益。图中流程可中断，不能为了完整性把未发生阶段填成已完成。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"本单元涉及方法判断，真实来源仅支持所列事实；图与教学构造分别保留其身份。"},"openQuestions":["未建立真实G2/G3或载体学习实例，不认证制度改进。","具体申诉的正当维持、纠错到达、残余伤害、未提交者与长期净收益须分开调查。"],"taskId":"S-A-7","sources":[{"id":"T-main","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§A.7，第3964—4029行","claim_support":["HV07完整39字段四路与分开结案规则。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"T-H3","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§7.1，第1469—1485行","claim_support":["H3分类规则的角色。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"T-D2","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§3.3，第463—472行","claim_support":["D2反馈定义。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"T-G2","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§4.4，第610—619行","claim_support":["返回通道效应。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"T-history","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§4.5，第620—641行","claim_support":["历史增量与当前载体路线。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"T-learning","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§4.11.3，第744—765行","claim_support":["C3反馈/学习条件。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"T-state","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§14.7，第2954—2967行","claim_support":["四个纠错终点与有据恢复。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"},{"id":"P-ROBO","title":"Royal Commission into the Robodebt Scheme：Report官网","url":"https://robodebt.royalcommission.gov.au/publications/report","source_type":"primary","version_or_date":"2023-07-07报告；07-11更正版说明","locator":"报告版本说明（网页行29—54）及建议13.1—13.2、17.1（行101—107、149—156）","claim_support":["官网记报告7月7日发布、7月11日更正；清单建议一线反馈和自动化决定复核。"],"limits":["本人读取官网清单和版本说明；未逐项比较两个PDF版本，未核建议落实，不把报告发布等同制度修复或学习。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-A-7/lecture.md","sourcesPath":"/reading-assets/S-A-7/sources.json","sourceSlicePath":"/reading-assets/S-A-7/source/S-A-7.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-A-7/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-a/a-07.md","filePath":"theory/appendix-a/a-07.md"}'),l={name:"theory/appendix-a/a-07.md"};function c(_,t,u,p,b,m){const e=a("SectionLesson");return r(),s("div",null,[t[0]||(t[0]=n("",1)),d(e,{section:"A.7"}),t[1]||(t[1]=o("div",{class:"theory-source"},null,-1))])}const f=i(l,[["render",c]]);export{T as __pageData,f as default};
